"[저주] — 다음 턴 전투가 시작될 때 그 턴 공격 −{0} · 방어 −(n÷3 올림). 드워프 유닛은 방어 −1 더. 그 뒤 꺼진다.": "[呪い] — 次のターンの戦闘開始時、そのターン攻撃−{0}・防御−(n÷3 切り上げ)。ドワーフのユニットはさらに防御−1。その後消える。",
