"가": "",
"가르운의 오크 족장": "ガルウンのオーク族長",
"강철은 물러서지 않는다": "鋼は退かない",
"거인 도르마크의 식지 않은 심장불이 깨운 것들 — 포르탄의 고블린 포병, 깨어난 화약, 불의 정령, 화산의 짐승. 광역 피해와 순간 화력이 강하지만, 쏜 다음 턴에는 장전해야 한다.": "巨人ドルマクの冷めない心火が目覚めさせたもの — フォルタンのゴブリン砲兵、目覚めた火薬、炎の精霊、火山の獣。範囲ダメージと瞬間火力に優れるが、撃った次のターンは装填が必要。",
"거인 소르그림의 힘줄 광맥에서 캔 쇠와 그 쇠가 깨운 것들 — 두르크하임의 드워프, 골렘 · 오토마톤, 깨어난 무구, 쇠를 먹는 짐승. 장갑으로 피해를 줄이며 버티지만 느리고 저주에 약하다.": "巨人ソルグリムの腱の鉱脈から掘った鉄と、その鉄が目覚めさせたもの — ドゥルクハイムのドワーフ、ゴーレム・オートマトン、目覚めた武具、鉄を喰らう獣。装甲でダメージを減らして耐えるが、遅く呪いに弱い。",
"거인 케라운의 번개 신경이 땅 위로 튄 것과 그것을 가둔 볼타리움의 노움 학자들 — 번개 정령, 축전 기계, 폭풍의 짐승. 충전을 쌓고 장치를 깔아 두었다가 한 번에 터뜨린다.": "巨人ケラウンの雷の神経が地上に弾けたものと、それを閉じ込めたヴォルタリウムのノーム学者たち — 雷の精霊、蓄電機械、嵐の獣。充電を溜め、装置を仕掛けておき、一気に炸裂させる。",
"고목뿔 용 베르단이 지키는 숲과 그 숲이 몸을 얻은 것들 — 실바니엘의 트롤, 트렌트 · 드라이어드, 버섯족, 숲의 짐승. 잘려도 다시 자라는 몸으로 가시로 피해를 돌려주고 재생하며 오래 버틴다. 불에 약하다.": "古木の角の竜ヴェルダンが守る森と、その森が体を得たもの — シルヴァニエルのトロール、トレント・ドライアド、キノコ族、森の獣。切られても再び伸びる体で、棘でダメージを返し、再生して長く耐える。火に弱い。",
