"턴마다 전투 시작 때 한 번 — 코인 앞면이면 첫 피해를 절반으로.": "ターンごとに戦闘開始時に一度 — コインが表なら最初のダメージを半分に。",
"턴마다 전투가 시작될 때 한 번(첫 마법 · 공격보다 먼저) 코인을 던져 앞면이면, 그 턴 처음 받는 피해 한 번(체력 깎임 포함)을 절반(올림)만큼 막는다.": "ターンごとに戦闘開始時に一度(最初の魔法・攻撃より先に)コインを投げ、表なら、そのターン最初に受けるダメージ一回(体力の減少を含む)を半分(切り上げ)防ぐ。",
