". 한 판 이길 때마다 카드 3장 중 1장을 골라 덱에 더하고, 지면 거기서 끝납니다 (얻은 카드는 남습니다).": "。勝つたびにカード3枚から1枚を選んでデッキに加え、負けるとそこで終わります(獲得したカードは残ります)。",
