"빈 자리": "空席",
"삼키는 자 · 여덟 번째 자리": "呑む者・八番目の座",
"새 원정": "新しい遠征",
"숲의 용": "森の竜",
"싸웁니다. 이웃 단체 둘 → 용 → 단체 → 용 → 동쪽의": "戦います。隣の団体二つ → 竜 → 団体 → 竜 → 東の",
"아우라곤의 파편 군도": "アウラゴンの破片諸島",
"아이템 비용이 0.": "アイテムのコストが0。",
"양쪽 유닛 전체 방어 +1.": "双方のユニット全体の防御+1。",
"양쪽 유닛 전체 체력 +2.": "双方のユニット全体の体力+2。",
"에 더해지고, 모험가의 보유 목록에도 영구히 남습니다.": "に加えられ、冒険者の所持リストにも永久に残ります。",
