"왕좌봉": "玉座峰",
"용은 카드가 아니라 그 땅의 법칙으로 나타납니다. 규칙은 양쪽 모두에게 적용됩니다.": "竜はカードではなく、その地の法則として現れます。ルールは双方に適用されます。",
