"결속한 아군이 쓰러지면 가진 피가 모두 바로 뒤 아군에게 옮겨 간다. 남의 피를 머금고 전투에서 살아남으면 다음 턴 준비 때 그 피 주인들이 쓰러질 때의 공격만큼 공격이 오른다(그 턴만).": "結束した味方が倒れると、持っていた血がすべてすぐ後ろの味方に移る。他者の血を宿して戦闘を生き延びると、次のターンの準備時にその血の持ち主たちが倒れた時の攻撃の分だけ攻撃が上がる(そのターンのみ)。",
