"으로, 상대 코인은 상대가 세웁니다(5초가 지나면 저절로 멈춤). 양쪽이 멈추면 나온 대로 스탯이 바뀐 뒤 공격 → 반격이 이어집니다. 피해 = 공격 − 방어(최소 0). 쓰러진 유닛과 쓴 마법은 그 자리에서 부서지고 남은 카드는 바로 왼쪽으로 당겨집니다. 피해는 그 턴 안에서만 쌓이고, 턴이 끝나면 회복됩니다.": "で止め、相手のコインは相手が止めます(5秒経つと自動で止まる)。両方が止まると出た通りにステータスが変わり、攻撃 → 反撃と続きます。ダメージ = 攻撃 − 防御(最小0)。倒れたユニットと使った魔法はその場で壊れ、残ったカードはすぐ左に詰められます。ダメージはそのターン内でのみ蓄積し、ターンが終わると回復します。",
"은 감소 효과를,": "は減少効果を、",
"은 증가 효과를 받지 않습니다(증가·감소 효과 = 마법·특수능력·코인·저주로 스탯이 오르내리는 것). 셋 다 받은 피해는 그대로 쌓이므로 체력만큼 피해를 입으면 쓰러집니다. 코인 때문에 체력이 0 이하가 되면 그 유닛은 쓰러져 소각 더미로 갑니다.": "は増加効果を受けません(増加・減少効果 = 魔法・特殊能力・コイン・呪いでステータスが上下すること)。三つとも受けたダメージはそのまま蓄積するので、体力分のダメージを受けると倒れます。コインのせいで体力が0以下になると、そのユニットは倒れて焼却の山へ行きます。",
"은 증가·감소 효과를 모두,": "は増加・減少効果をすべて、",
"을": "",
"을 내고 그 코인만 다시 던집니다. 맞붙을 때마다 한 번(이미 정해진 방어 코인은 다시 던질 수 없음). 준비 단계에서 남겨 둔 에테르를 여기에 씁니다 (남은 에테르는 다음 턴으로 넘어가지 않습니다).": "を払ってそのコインだけ投げ直します。激突ごとに一回(すでに決まった防御コインは投げ直せない)。準備フェイズで残したエーテルをここで使います(残ったエーテルは次のターンに持ち越されません)。",
