"척후병": "斥候",
"첫 핸드에서 고른 카드를 한 번 바꿉니다. 생명은 줄지 않습니다.": "最初の手札から選んだカードを一度交換します。ライフは減りません。",
"체력 −2 −1●": "体力−2 −1●",
"체력 −N": "体力−N",
"체력을 깎습니다 — 맞붙기 · 반격 · 투척 · 연쇄 · 꿰뚫기, 그리고": "体力を削ります — 激突・反撃・投擲・連鎖・貫通、そして",
"체력이 0이 되는 유닛은 쓰러집니다": "体力が0になるユニットは倒れます",
"체력이 N 깎입니다 — 대부분의 마법 · 사격 · 불씨 · 축전.": "体力がN削られます — ほとんどの魔法・射撃・火種・蓄電。",
"출정의 단": "出陣の壇",
"카드 숫자 옆": "カードの数字の横の",
"카드 이름 아래 · 상점 단추 옆의 색이 등급입니다. 희귀할수록 상점 재고가 적습니다. 유니크 · 스페셜 · 강화는 덱에 한 장만 넣을 수 있습니다. 강화는 같은 카드 3장을 합쳐서만 얻습니다.": "カード名の下・ショップのボタン横の色が等級です。希少なほどショップの在庫が少なくなります。ユニーク・スペシャル・強化はデッキに一枚しか入れられません。強化は同じカード3枚を合わせてのみ得られます。",
"카드 읽기": "カードの読み方",
"카드를 내는 힘.": "カードを出す力。",
"카드를 내면 결정이 어두워진다": "カードを出すと結晶が暗くなる",
"카드를 누르면 상대 전장 오른쪽에 원본 카드가 크게 뜹니다(레벨 · 클래스 · 설명 · 지금 스탯). 내 카드면 왼쪽에 단추도 나옵니다. 다시 누르기 · 빈 곳 누르기 · Esc로 닫습니다. 소각장을 누르면 맨 위 카드를 봅니다.": "カードを押すと相手の戦場の右に元のカードが大きく出ます(レベル・クラス・説明・今のステータス)。自分のカードなら左にボタンも出ます。もう一度押す・空いた所を押す・Escで閉じます。焼却場を押すと一番上のカードを見られます。",
"카드를 뽑을 때마다": "カードを引くたびに",
"카드에 적힌 앞쪽부터": "カードに書かれた前のものから",
"칸 번호 순서대로 진행된다 — 1 · 2번이 공격하고, 3번 공격 마법이 뒤집혀 발동하고, 4번 기사가 공격한다.": "スロット番号順に進む — 1・2番が攻撃し、3番の攻撃魔法が裏返って発動し、4番の騎士が攻撃する。",
"칸 없이 바로 발동": "スロットなしで即発動",
"칸에 서서 싸운다 · 유지비": "スロットに立って戦う・維持費",
"칼 · 방패 · 핏방울은 공격 · 방어 · 체력,": "剣・盾・血の滴は攻撃・防御・体力、",
