"코인 때문에 체력이 0 이하가 되면 그 유닛은 쓰러집니다.": "コインのせいで体力が0以下になると、そのユニットは倒れます。",
"코인 멈추기(운명 봉인)": "コインを止める(運命封印)",
"코인을 건드리는 마법은 아직 던지지 않은 코인에만 듣습니다.": "コインに作用する魔法は、まだ振っていないコインにのみ効きます。",
"코인을 다시 던집니다": "コインを振り直します",
