"튜토리얼 · 매뉴얼 · 룰북": "チュートリアル・マニュアル・ルールブック",
"튜토리얼 · 전투 배우기": "チュートリアル・戦闘を学ぶ",
"튜토리얼 목록": "チュートリアル一覧",
"튜토리얼은 상단 띠의 퀘스트 옆, 매뉴얼 · 룰북은": "チュートリアルは上部バーのクエストの隣、マニュアル・ルールブックは",
"튜토리얼은 언제든 여기서 다시.": "チュートリアルはいつでもここからもう一度。",
