"/* 고리 안의 필멸자 땅: 서북 아다만트의 용광로 불 · 서남 푸른숲의 숲빛 · 동 비술의 흰 첨탑 불빛 */": "/* 環の内の定命の者の地: 北西アダマントの溶鉱炉の火 · 南西青き森の森光 · 東の秘術の白い尖塔の灯 */",
