"/* 동쪽 너머의 빈 땅: 색이 빠지고 고리의 선도 지워진다 */": "/* 東の彼方の空白の地: 色が抜け、環の線も消える */",
"/* 빈 땅: 회색 번짐과 잔금 */": "/* 空白の地: 灰色のにじみと細いひび */",
