"1.5) { /* 비늘 */": "1.5) { /* 鱗 */",
"4.5) { /* 옷: 아래로 흐르는 결 */": "4.5) { /* 衣: 下へ流れる筋 */",
"if (m > 7.5) { /* 용의 일곱 보석: 머리에서 꼬리로 차례로 반짝인다 */": "if (m > 7.5) { /* 竜の七つの宝石: 頭から尾へ順にきらめく */",
