"모험가로 등록한 뒤에 살 수 있습님.": "冒険者として登録した後に購入できます。",
"모험가를 지웠습님. 그동안 고마웠습님.": "冒険者を削除しました。今までありがとうございました。",
"몰릴수록 송곳니는 날카로워짐": "追い詰められるほど牙は鋭くなる",
"무엇이든 제안하세요. 올린 사람이 골라야 성사됩님.": "何でも提案してください。出品者が選ぶと成立します。",
"문양 셋이 맞으면 상을 받습님. 두 곳에서 같은 표로 굴립님.": "紋様が三つそろうと賞がもらえます。二か所で同じ表を使って回します。",
"물때를 받아 이번 턴 공격이 올랐음.": "潮時を受け、このターン攻撃が上がった。",
"물때를 받아 이번 턴 방어가 올랐음.": "潮時を受け、このターン防御が上がった。",
"물은 모든 상처를 씻음": "水はすべての傷を洗う",
"물을 주었음": "水をやった",
"바꾸면 준비가 풀립님": "変更すると準備が解除されます",
