"바뀐 것이 없습님": "変更はありません",
"바람을 읽는 화살은 빗나가지 않음": "風を読む矢は外れない",
"바로 뒤에 아군 유닛이 없어 효과가 없음": "すぐ後ろに味方ユニットがいないため効果なし",
"받았습님": "受け取りました",
"받은 피해가 턴이 끝나도 낫지 않음.": "受けたダメージはターン終了後も回復しない。",
"받은 피해는 그 턴 안에서만 쌓이고, 턴이 끝나면 낫습님.": "受けたダメージはそのターン内だけ蓄積し、ターンが終わると回復します。",
