"방금 코드를 보냈습님. 1분 뒤에 다시 받을 수 있습님.": "たった今コードを送りました。1分後に再度受け取れます。",
"방어 마법은 내 방어 턴에만 쓸 수 있습님.": "防御魔法は自分の防御ターンにのみ使えます。",
"방어가 0인 상대 유닛이 없어 효과가 없음": "防御0の相手ユニットがいないため効果なし",
"방어를 가진 상대 유닛이 없어 덩굴이 헛돌았음": "防御を持つ相手ユニットがいないため蔓は空回りした",
"방어하는 쪽 코인은 한 전투에서 한 번만 던짐": "防御側のコインは一回の戦闘で一回だけ投げる",
"방에 있지 않습님.": "ルームにいません。",
"방을 너무 자주 만들었습님. 잠시 뒤에 다시 해 주세요.": "ルームを作る頻度が高すぎます。しばらくしてからもう一度お試しください。",
"방을 만들지 못했습님.": "ルームを作れませんでした。",
"방을 열고 코드를 친구에게 알려 줍님.": "ルームを開いてコードを友達に伝えます。",
"방을 열지 못했습님. 잠시 뒤 다시 해 주세요.": "部屋を開けませんでした。しばらくしてからもう一度お試しください。",
"방이 가득 찼습님.": "ルームが満員です。",
"방이 가득 찼습님. 잠시 뒤에 다시 해 주세요.": "ルームが満員です。しばらくしてからもう一度お試しください。",
"방이 방금 닫혔습님.": "ルームがたった今閉じました。",
"방장과 연결하지 못했습님. (네트워크가 막혀 있을 수 있어요)": "ホストと接続できませんでした。(ネットワークが遮断されている可能性があります)",
"방장과 연결하지 못했습님. 다시 준비해 주세요.": "ホストと接続できませんでした。もう一度準備してください。",
"방장만 내보낼 수 있습님.": "ホストのみ退出させられます。",
"방장만 시작할 수 있습님.": "ホストのみ開始できます。",
"방장이 내보냈습님.": "ホストに退出させられました。",
"방장이 대전을 시작하기를 기다립님.": "ホストが対戦を開始するのを待っています。",
"번갈아 발동합님(한쪽만 남으면 그쪽을 칸 번호 순으로).": "と交互に発動します(片方だけ残ればその側をスロット番号順に)。",
"벌어들인 조각이 곧 경험치입님(사도 줄지 않음, 판매 · 거래로 받은 조각은 빼고). 최대 Lv {level.max}.": "稼いだ欠片がそのまま経験値です（買っても減らず、販売・取引で得た欠片は除く）。最大Lv {level.max}。",
"벌어들인 환석 조각이 곧 경험치입님. 카드를 사도 줄지 않고, 판 값은 경험치가 되지 않습님.": "稼いだ幻石の欠片がそのまま経験値です。カードを買っても減らず、対戦の賭け金は経験値になりません。",
"별을 읽는 신 벨루미르의 앎과 별과 바람이 부른 것들 — 폭풍탑의 엘프 사수, 몸을 얻은 별자리와 책, 바람을 타는 짐승. 몸은 약하지만, 멀리서 쏘아 갑옷 틈을 꿰뚫고 칼이 닿기 전에 물러섬.": "星を読む神ベルミルの知と、星と風が呼んだもの — 嵐の塔のエルフ射手、体を得た星座と書物、風に乗る獣。体は弱いが、遠くから撃って鎧の隙間を貫き、刃が届く前に退く。",
"별이 {0}개 있어야 엽님.": "星が{0}個必要です。",
