"필요 없는 카드는 소각장에 버립니다 (X)": "いらないカードは焼却場に捨てます (X)",
"핸드가 마음에 안 들면 셔플 — 덱에 섞고 새로 뽑습니다 (S)": "手札が気に入らなければシャッフル — デッキに混ぜて引き直します (S)",
"셔플은 한 턴에 한 번, 카드를 내기 전에만. 생명 1을 냅니다.": "シャッフルは1ターンに1回、カードを出す前だけ。生命1を払います。",
